const raw = $input.first().json.body ?? $input.first().json;
const eventType = raw.eventType ?? '';
const instance = $env.EVO_BETHANIA_INSTANCE || 'bethania';
const base = ($env.EVO_API_BASE_URL || '').replace(/\/$/, '');
const apiKey = $env.EVO_API_KEY || '';

let action = 'noop';
let request = null;

if (eventType === 'studio_bot.channel_reconnect') {
  action = 'evolution';
  request = {
    method: 'GET',
    url: `${base}/instance/connect/${encodeURIComponent(instance)}`,
    headers: { apikey: apiKey },
  };
} else if (eventType === 'studio_bot.channel_sync_profile') {
  action = 'evolution';
  const updates = [];
  if (raw.displayName) {
    updates.push({
      method: 'POST',
      url: `${base}/chat/updateProfileName/${encodeURIComponent(instance)}`,
      headers: { apikey: apiKey, 'Content-Type': 'application/json' },
      body: { name: raw.displayName },
    });
  }
  if (raw.aboutText) {
    updates.push({
      method: 'POST',
      url: `${base}/chat/updateProfileStatus/${encodeURIComponent(instance)}`,
      headers: { apikey: apiKey, 'Content-Type': 'application/json' },
      body: { status: raw.aboutText },
    });
  }
  request = updates[0] ?? null;
} else if (eventType === 'studio_bot.test_ping') {
  action = 'ping';
} else if (raw.normalizedPhone && raw.message) {
  action = 'evolution';
  const phone = String(raw.normalizedPhone).replace(/\D/g, '');
  const text = String(raw.message);
  if (raw.requiresHsm) {
    request = {
      method: 'POST',
      url: `${base}/message/sendTemplate/${encodeURIComponent(instance)}`,
      headers: { apikey: apiKey, 'Content-Type': 'application/json' },
      body: {
        number: phone,
        name: 'bethania_meeting_reminder',
        language: 'pt_BR',
        components: [
          {
            type: 'body',
            parameters: [{ type: 'text', text }],
          },
        ],
      },
    };
  } else {
    request = {
      method: 'POST',
      url: `${base}/message/sendText/${encodeURIComponent(instance)}`,
      headers: { apikey: apiKey, 'Content-Type': 'application/json' },
      body: { number: phone, text, linkPreview: true },
    };
  }
}

return [{ json: { action, request, eventType, raw } }];
